/*
 * prog30_escape_unescape – reproduced from the obfuscated binary.
 *
 * Behaviour:
 *   prog30_escape_unescape <mode> <string>
 *
 *   <mode>   : "escape"   – produce an escaped representation of <string>
 *              "unescape" – interpret escaped sequences in <string>
 *
 *   The program prints the resulting string on stdout.
 *
 *   Errors:
 *     * Wrong number of arguments          → prints "USAGE"
 *     * Unknown mode                       → prints "INVALID_MODE"
 *     * Input longer than 1023 characters  → prints "INVALID"
 *     * Invalid escape sequence (unescape) → prints "INVALID"
 *
 *   The implementation follows the logic that was discovered in the
 *   decompiled state‑machine: only the three escape sequences
 *   \"  \\  \n  are recognised.  All other characters are passed through
 *   unchanged.
 */

#include <stdio.h>
#include <string.h>
#include <stdlib.h>

#define MAX_INPUT  1023                 /* limit observed in the original binary */
#define MAX_OUTPUT (MAX_INPUT * 2 + 1)  /* worst case: every char becomes \\ */

/* --------------------------------------------------------------------- */
/* Escape a string: backslash, double‑quote and newline are escaped.      */
static int escape_string(const char *in, char *out, size_t out_sz)
{
    size_t i = 0, o = 0;
    while (in[i] != '\0')
    {
        char c = in[i];
        if (c == '\\')
        {
            if (o + 2 >= out_sz) return -1;
            out[o++] = '\\';
            out[o++] = '\\';
        }
        else if (c == '"')
        {
            if (o + 2 >= out_sz) return -1;
            out[o++] = '\\';
            out[o++] = '"';
        }
        else if (c == '\n')
        {
            if (o + 2 >= out_sz) return -1;
            out[o++] = '\\';
            out[o++] = 'n';
        }
        else
        {
            if (o + 1 >= out_sz) return -1;
            out[o++] = c;
        }
        ++i;
    }
    out[o] = '\0';
    return 0;
}

/* --------------------------------------------------------------------- */
/* Un‑escape a string: recognises \\  \"  \n .  Anything else is error.   */
static int unescape_string(const char *in, char *out, size_t out_sz)
{
    size_t i = 0, o = 0;
    while (in[i] != '\0')
    {
        if (in[i] != '\\')
        {
            if (o + 1 >= out_sz) return -1;
            out[o++] = in[i++];
            continue;
        }

        /* we have a backslash – need a following character */
        if (in[i + 1] == '\0')
            return -1;               /* stray backslash */

        char nxt = in[i + 1];
        if (nxt == '\\')
        {
            if (o + 1 >= out_sz) return -1;
            out[o++] = '\\';
        }
        else if (nxt == '"')
        {
            if (o + 1 >= out_sz) return -1;
            out[o++] = '"';
        }
        else if (nxt == 'n')
        {
            if (o + 1 >= out_sz) return -1;
            out[o++] = '\n';
        }
        else
        {
            return -1;               /* unknown escape sequence */
        }
        i += 2;                      /* consumed the two‑character escape */
    }
    out[o] = '\0';
    return 0;
}

/* --------------------------------------------------------------------- */
int main(int argc, char *argv[])
{
    if (argc < 3)                     /* not enough arguments */
    {
        puts("USAGE");
        return 0;
    }

    const char *mode  = argv[1];
    const char *input = argv[2];

    if (strlen(input) > MAX_INPUT)    /* original binary limits the input */
    {
        puts("INVALID");
        return 0;
    }

    char outbuf[MAX_OUTPUT];

    if (strcmp(mode, "escape") == 0)
    {
        if (escape_string(input, outbuf, sizeof outbuf) != 0)
        {
            puts("INVALID");
            return 0;
        }
        puts(outbuf);
    }
    else if (strcmp(mode, "unescape") == 0)
    {
        if (unescape_string(input, outbuf, sizeof outbuf) != 0)
        {
            puts("INVALID");
            return 0;
        }
        puts(outbuf);
    }
    else
    {
        puts("INVALID_MODE");
    }

    return 0;
}
